package Lec1;

public class Odd_Even {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int n = 89;
		if(n>160) {// yes
			System.out.println("Yes");
		}
		
		if(n%2==0) {// yes
			System.out.println("Even");
		}
		else {// No
			System.out.println("Odd");
		}

	}

}
